INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7188855, 1105265, 96574, '<td valign="top">portrait, shallow dof, shoehorn.<br/>oh wait, shoehorn is more of a dpc technique, not a photographic technique.<br/> <br/>kidding aside, pretty nice portrait with interesting elements.  would''ve been nicer with the sun lower in the sky but i''m sure you already knew that.</td>', 'portrait, shallow dof, shoehorn.oh wait, shoehorn is more of a dpc technique, not a photographic technique. kidding aside, pretty nice portrait with interesting elements.  would''ve been nicer with the sun lower in the sky but i''m sure you already knew that.', '2014-03-12 00:10:38.000000', NULL, 1),
(7188866, 1105573, 30861, '<td valign="top">Lovely B/W rendering, great mood, excellent image in all regards. Leading Lines, check. Deep DOF, check. Centered Composition, though? No way. All the mass is on the right and diminishing to the left.</td>', 'Lovely B/W rendering, great mood, excellent image in all regards. Leading Lines, check. Deep DOF, check. Centered Composition, though? No way. All the mass is on the right and diminishing to the left.', '2014-03-12 00:23:14.000000', NULL, 1),
