(7189030, 1105265, 54446, '<td valign="top">Good photo which DNMC because of the absence of techniques listed in title.</td>', 'Good photo which DNMC because of the absence of techniques listed in title.', '2014-03-12 10:54:04.000000', NULL, 1),
(7189034, 1105603, 54446, '<td valign="top">Not Deep DOF.  The other two techniques are not listed as available techniques.  You could have listed blur, stop action and rule of thirds, for example and scored very well with this image.</td>', 'Not Deep DOF.  The other two techniques are not listed as available techniques.  You could have listed blur, stop action and rule of thirds, for example and scored very well with this image.', '2014-03-12 11:03:27.000000', NULL, 1),
